class Show(GenericcFsclishCommand):
    """Show command class."""

    def __init__(self, connection, options, value=None, prompt=None, newline_chars=None, runner=None):
        """
        Show command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the show command will be executed
                    flexizone access-point summary
                    flexizone access-point service-account credentials
                    flexizone dhcp
                    flexizone lpki-backhaul
                    flexizone shared-backhaul state
                    security cert default cmp
                    flexizone access-point port
                    networking address iface
                    fzc-ipsec
        :param value: necessary parameter for:
                    networking address iface
                    fzc-ipsec
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Show, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.value = value
        self.ret_required = False
        self.headers = []
        self.current_ret["RESULT"] = []
        self.flag_abbreviations = None
        self.iface = None
        self.counter = -1

        self._parse_public_key_started = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "show"
        cmd = f"{cmd} {self.options}"
        if self.value:
            cmd = f"{cmd} {self.value}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_separated_line(line)
                self._start_parse_flexizone_dhcp(line)
                self._start_parse_networking_address_iface(line)
                self._start_parse_one_row_output(line)
                self._start_parse_security_cert_default_cmp(line)
                self._start_parse_fzc_ipsec(line)
                self._start_parse_flexizone_access_point_port(line)
                self._start_parse_flexizone_access_point_summary(line)
                self._start_parse_flexizone_access_point_service_account_credentials(line)
                self._parse_public_key(line)
            except ParsingDone:
                pass
        return super(Show, self).on_new_line(line, is_full_line)

    def _start_parse_networking_address_iface(self, line):
        """
        Start parsing methods if parameter options = 'networking address iface'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "networking address iface":
            self._parse_networking_address_iface_name(line)
            self._parse_networking_address_iface_details(line)
            self._parse_networking_address_iface_details_user(line)

    def _start_parse_fzc_ipsec(self, line):
        """
        Start parsing methods if parameter options = 'fzc-ipsec'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "fzc-ipsec":
            self._parse_abbreviations(line)
            self._parse_abbreviations_details(line)
            self._parse_total_rule_number(line)
            self._parse_fzc_ipsec_sb_protect_allzone(line)

    def _start_parse_flexizone_access_point_summary(self, line):
        """
        Start parsing methods if parameter options = 'flexizone access-point summary'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "flexizone access-point summary":
            self._parse_flexizone_access_point(line)
            self._parse_table_output(line)

    def _start_parse_flexizone_access_point_service_account_credentials(self, line):
        """
        Start parsing methods if parameter options = 'flexizone access-point service-account credentials'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "flexizone access-point service-account credentials":
            self._parse_table_output(line)

    def _start_parse_one_row_output(self, line):
        """
        Start parsing methods if parameter options = 'flexizone lpki-backhaul' or options= 'flexizone shared-backhaul state'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "flexizone lpki-backhaul" or self.options == "flexizone shared-backhaul state":
            self._parse_one_row_output(line)

    def _start_parse_flexizone_dhcp(self, line):
        """
        Start parsing methods if parameter options = 'flexizone dhcp'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "flexizone dhcp":
            self._parse_table_output(line)

    def _start_parse_security_cert_default_cmp(self, line):
        """
        Start parsing methods if parameter options = 'security cert default cmp'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "security cert default cmp":
            self._parse_security_cert_default_cmp(line)

    def _start_parse_flexizone_access_point_port(self, line):
        """
        Start parsing methods if parameter options = 'flexizone access-point port'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "flexizone access-point port":
            self._parse_flexizone_access_point_port(line)

    _re_separated_line = re.compile(r"(---)")

    def _parse_separated_line(self, line):
        """
        Check if line contains at least 3 dash sign. example line:.

        '-----------------------------------------------------------------------'.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Show._re_separated_line, line):
            raise ParsingDone

    _re_flexizone_access_point = re.compile(r"(flexizone\saccess\spoint\s.*:)")

    def _parse_flexizone_access_point(self, line):
        """
        Check if line contains 'flexizone access point' egample line:.

        'flexizone access point summary:'.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Show._re_flexizone_access_point, line):
            raise ParsingDone

    _re_header_table = re.compile(r"(\S+(\s\S+)*)")

    def _parse_table_output(self, line):
        """
        Parse simple tabular output. example:.

        'AP ID   Node ID   Ip.
        1       0x213d    192.168.55.2'

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_header_table, line):
            if not self.headers:
                for value in re.findall(Show._re_header_table, line):
                    self.headers.append(value[0])
                raise ParsingDone
            else:
                ret = {}
                values = re.findall(Show._re_header_table, line)
                if not len(self.headers) == len(values):
                    self.set_exception(CommandFailure(self, "ERROR: Invalid arguments all list should have the same length"))
                else:
                    for index in range(len(self.headers)):
                        ret[self.headers[index]] = values[index][0]
                    self.current_ret["RESULT"].append(ret)
                raise ParsingDone

    _re_headers_fzc_ipsec_sb_protect_allzone = re.compile(r"([A-Z][\w]+(\s[a-z]+)?)")
    _re_values_fzc_ipsec_sb_protect_allzone = re.compile(r"(?P<VALUE>(\S+))")

    def _parse_fzc_ipsec_sb_protect_allzone(self, line):
        """
        Parse tabular output dedicate for fzc-ipsec sb protec allzone. example:.

        Rule name                Owner    Src addr.
        BYPASS-UPLANE-NOKIA-2152 /FZBU-0  0.0.0.0/0

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_headers_fzc_ipsec_sb_protect_allzone, line):
            if not self.headers:
                for value in re.findall(Show._re_headers_fzc_ipsec_sb_protect_allzone, line):
                    self.headers.append(value[0])
                raise ParsingDone
            else:
                ret = {}
                values = re.findall(Show._re_values_fzc_ipsec_sb_protect_allzone, line)
                if not len(self.headers) == len(values):
                    self.set_exception(CommandFailure(self, "ERROR: Invalid arguments all list should have the same length"))
                else:
                    for index in range(len(self.headers)):
                        ret[self.headers[index]] = values[index][0]
                    self.current_ret["RESULT"].append(ret)
                raise ParsingDone

    _re_one_row_output = re.compile(r"(LPKI\sfor\sshared\sbackhaul\sis|Shared\sbackhaul\sstate:)\s(?P<STATUS>.*)")

    def _parse_one_row_output(self, line):
        """
        Parse siple one row output. example:.

        'LPKI for shared backhaul is disabled'.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_one_row_output, line):
            ret = {}
            ret["STATUS"] = self._regex_helper.group("STATUS")
            self.current_ret["RESULT"].append(ret)
            raise ParsingDone

    _re_security_cert_default_cmp = re.compile(r"(?P<KEY>(\S+\s+)*\S+)\s*:\s+(?P<VALUE>.*)")

    def _parse_security_cert_default_cmp(self, line):
        """
        Parse key : value output. Example:.

        'Port  :  8080'

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_security_cert_default_cmp, line):
            ret = {}
            ret[self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            self.current_ret["RESULT"].append(ret)
            raise ParsingDone

    _re_abbreviations = re.compile(r"^(?P<ABBREVIATIONS>\w.*):$")

    def _parse_abbreviations(self, line):
        """
        Set the flag 'flag_abbreviations' if parse line. example:.

        'Abbreviations:'.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_abbreviations, line):
            self.flag_abbreviations = True
            ret = {}
            ret["ABBREVIATIONS"] = {}
            self.current_ret["RESULT"].append(ret)
            raise ParsingDone

    _re_abbreviations_details = re.compile(r"\s+(?P<KEY>.*)\s+:\s+(?P<VALUE>.*)")

    def _parse_abbreviations_details(self, line):
        """
        Parse key : value output dedicate for abbreviations case. Example:.

        '  Src addr : source address'

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_abbreviations_details, line):
            if self.flag_abbreviations:
                for index in range(len(self.current_ret["RESULT"])):
                    self.current_ret["RESULT"][index]["ABBREVIATIONS"][self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    _re_total_rule_number = re.compile(r"^(\w.*):\s(?P<NUMBER>\d+)$")

    def _parse_total_rule_number(self, line):
        """
        Parse one row output contains phrase and digit. example:.

        'Total rule number: 2'.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_total_rule_number, line):
            ret = {}
            ret["TOTAL_RULE_NUMBER"] = self._regex_helper.group("NUMBER")
            self.current_ret["RESULT"].append(ret)
            raise ParsingDone

    _re_networking_address_iface_name = re.compile(r"^\s{2}(?P<IFACE>\S+)")

    def _parse_networking_address_iface_name(self, line):
        """
        Create dictionary with interface name for interface details:.

        '  nbmplane'.
        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_networking_address_iface_name, line):
            self.iface = self._regex_helper.group("IFACE")
            self.counter += 1
            ret = {}
            ret[self.iface] = {}
            self.current_ret["RESULT"].append(ret)
            raise ParsingDone

    _re_networking_address_iface_details = re.compile(r"^\s{4}(?P<KEY>\S+(\s\S+)*)\s+:\s(?P<VALUE>.*)")
    _re_address_and_netmask = re.compile(r"(?P<ADDRESS>\d+\.\d+\.\d+\.\d+)\/(?P<NETMASK>\d+)")

    def _parse_networking_address_iface_details(self, line):
        """
        Create dictionary interface details:.

        '    address       : 10.89.29.14/32'

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_networking_address_iface_details, line):
            if self._regex_helper.group("KEY") == "user":
                self.current_ret["RESULT"][self.counter][self.iface]["user"] = []
                self.current_ret["RESULT"][self.counter][self.iface]["user"].append(self._regex_helper.group("VALUE"))
            else:
                key = self._regex_helper.group("KEY")
                value = self._regex_helper.group("VALUE")
                if self._regex_helper.search_compiled(Show._re_address_and_netmask, value):
                    self.current_ret["RESULT"][self.counter][self.iface]["address"] = self._regex_helper.group("ADDRESS")
                    self.current_ret["RESULT"][self.counter][self.iface]["netmask"] = self._regex_helper.group("NETMASK")
                else:
                    self.current_ret["RESULT"][self.counter][self.iface][key] = value
            raise ParsingDone

    _re_networking_address_iface_details_user = re.compile(r"\s{6,}(?P<USER>.*)")

    def _parse_networking_address_iface_details_user(self, line):
        """
        Create list of users assigned to the interface. example:.

        '    user          : /MgmtIP'

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_networking_address_iface_details_user, line):
            if self.current_ret["RESULT"][self.counter][self.iface]["user"]:
                self.current_ret["RESULT"][self.counter][self.iface]["user"].append(self._regex_helper.group("USER"))
                raise ParsingDone

    _re_header_flexizone_access_point_port = re.compile(r"(?P<ID>\S+\s\S+)?\s(?P<PORT>\S+\s\S+),\s+(?P<TIMEOUT>\S+)")
    _re_detaills_access_point_port = re.compile(r"(?P<ID>\d+)?\s+(?P<PORT>\S+),\s+(?P<TIMEOUT>[\d-]+)")

    def _parse_flexizone_access_point_port(self, line):
        """
        Parse table output dedicate for access pint port. example:.

        'AP ID Debug Port, Timeout Ssh/Local Port, Timeout EmMgmt/WebUI/BTSSM Ports,  Timeout.
        1     disabled,   -       disabled,       10       disabled,                  -'

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_header_flexizone_access_point_port, line):
            self.headers = re.findall(Show._re_header_flexizone_access_point_port, line)
            raise ParsingDone
        if self._regex_helper.search_compiled(Show._re_detaills_access_point_port, line):
            ret = re.findall(Show._re_detaills_access_point_port, line)
            if not len(self.headers) == len(ret):
                self.set_exception(CommandFailure(self, "ERROR: Invalid arguments all list should have the same length"))
            else:
                for i in range(len(self.headers)):
                    if not self.headers[i][0] == "" and not ret[i][0] == "":
                        tmp_dict = {}
                        tmp_dict[ret[i][0]] = []
                        self.current_ret["RESULT"].append(tmp_dict)
                        self.counter += 1
                        self.iface = ret[i][0]
                    else:
                        tmp_dict = {}
                        tmp_dict[self.headers[i][1]] = ret[i][1]
                        tmp_dict[self.headers[i][2]] = ret[i][2]
                        self.current_ret["RESULT"][self.counter][self.iface].append(tmp_dict)
            raise ParsingDone

    _re_ssh_public_key = re.compile(r"(?P<ID>\d+)\.\s+(?P<SSH_KEY>ssh-rsa.*)")

    def _parse_public_key(self, line):
        """
        Parse ssh public key.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Show._re_ssh_public_key, line):
            self._parse_public_key_started = True
            ssh_key = {"Index": self._regex_helper.group("ID"), "Key": self._regex_helper.group("SSH_KEY")}
            self.current_ret["RESULT"].append(ssh_key)
            raise ParsingDone
        elif self._parse_public_key_started:
            # WA - Public key is very long(more than 300 chars). Needs to concatenate
            rest_of_key = line
            self.current_ret["RESULT"][-1]["Key"] = self.current_ret["RESULT"][-1]["Key"] + rest_of_key
            raise ParsingDone


